export function hebrewSpeech(text) {
  return text.replace(/[\u0590-\u05ff]+/gu, word => {
    const phonemes = HEBREW_LEXICON[word.normalize('NFC')];
    if (!phonemes) throw new Error(`Hebrew word needs pronunciation review: ${word}`);
    return phonemes;
  });
}
